      {"kind": "appearsBy", "selector": "#final-state", "bySec": 15.8},
      {"kind": "appearsBy", "selector": "#recap", "bySec": 20.5},
      {"kind": "appearsBy", "selector": "#boundary", "bySec": 20.5},
      {"kind": "staysInFrame", "selector": "#title"},
      {"kind": "staysInFrame", "selector": "#shared-chart"},
      {"kind": "staysInFrame", "selector": "#final-state"},
      {"kind": "staysInFrame", "selector": "#boundary"},
      {"kind": "staysInFrame", "selector": "#footer"}
    ]
